arguments.content:
#!/usr/bin/env python3

import csv
import json
import re
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


THERAPY_CATALOG_PATH = Path("/root/therapy_catalog.json")
BAG_SUPPLY_COST_PATH = Path("/root/bag_supply_cost.csv")
DELIVERY_PAYMENT_PATH = Path("/root/delivery_payment.csv")
PATIENT_OVERRIDES_PATH = Path("/root/patient_overrides.csv")

OUTPUT_ANALYSIS_PATH = Path("/root/infusion_batch_analysis.json")
OUTPUT_SUMMARY_PATH = Path("/root/infusion_batch_summary.md")


def _norm_label(value: str) -> str:
    if value is None:
        return ""
    return re.sub(r"[^a-z0-9]+", "", str(value).strip().lower())


def _is_true(value) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() == "true"


def _to_int(value, default=0) -> int:
    if value is None:
        return default
    s = str(value).strip()
    if s == "":
        return default
    return int(float(s))


def _to_decimal(value, default="0") -> Decimal:
    if value is None:
        return Decimal(default)
    s = str(value).strip()
    if s == "":
        return Decimal(default)
    # Use Decimal(str(...)) for stable parsing
    return Decimal(s)


def _money_decimal(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _money_str(value: Decimal) -> str:
    return f"{_money_decimal(value):.2f}"


def _read_csv_dicts(path: Path):
    with path.open("r", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        return list(reader)


def _iter_catalog_therapies(catalog_obj):
    """Yield therapy dicts regardless of whether catalog is list/dict/nested."""
    if isinstance(catalog_obj, list):
        for item in catalog_obj:
            if isinstance(item, dict) and ("therapy_code" in item or "therapy_name" in item):
                yield item
            elif isinstance(item, dict):
                # Possibly nested
                yield from _iter_catalog_therapies(item)
        return

    if isinstance(catalog_obj, dict):
        if "therapy_code" in catalog_obj or "therapy_name" in catalog_obj:
            yield catalog_obj
            return

        # Common nesting patterns
        if "therapies" in catalog_obj and isinstance(catalog_obj["therapies"], list):
            for t in catalog_obj["therapies"]:
                if isinstance(t, dict):
                    yield t
            return

        if "service_lines" in catalog_obj and isinstance(catalog_obj["service_lines"], list):
            for sl in catalog_obj["service_lines"]:
                yield from _iter_catalog_therapies(sl)
            return

        # Fallback: recurse dict values
        for v in catalog_obj.values():
            yield from _iter_catalog_therapies(v)


def _get_aliases(therapy_entry):
    aliases = []
    for key in ("aliases", "alias", "aka", "alternate_names", "alt_names"):
        if key not in therapy_entry:
            continue
        v = therapy_entry.get(key)
        if v is None:
            continue
        if isinstance(v, list):
            aliases.extend([str(x) for x in v if str(x).strip() != ""])
        else:
            s = str(v).strip()
            if s:
                aliases.append(s)
    return aliases


def main():
    # Load therapy catalog
    with THERAPY_CATALOG_PATH.open("r", encoding="utf-8") as f:
        catalog = json.load(f)

    all_therapies = list(_iter_catalog_therapies(catalog))
    in_scope = [t for t in all_therapies if _is_true(t.get("include_in_review"))]

    # Index in-scope therapies
    therapies_by_code = {}
    for t in in_scope:
        code = str(t.get("therapy_code", "")).strip()
        if not code:
            continue
        therapies_by_code[code] = t

    in_scope_codes = set(therapies_by_code.keys())

    # Load bag supply costs
    bag_rows = _read_csv_dicts(BAG_SUPPLY_COST_PATH)
    bag_cost_by_size_ml = {}
    for r in bag_rows:
        size_ml = _to_int(r.get("bag_size_ml"))
        cost = _to_decimal(r.get("bag_supply_cost_usd"))
        bag_cost_by_size_ml[size_ml] = cost

    # Resolve delivery payments by matching therapy_label to therapy name OR alias
    payment_rows = _read_csv_dicts(DELIVERY_PAYMENT_PATH)

    label_to_code = {}
    # Deterministic: build labels in therapy_code sort order
    for code in sorted(in_scope_codes):
        t = therapies_by_code[code]
        names = [t.get("therapy_name")]
        names.extend(_get_aliases(t))
        for name in names:
            if name is None:
                continue
            norm = _norm_label(name)
            if not norm:
                continue
            # Keep first mapping for determinism if collisions exist
            label_to_code.setdefault(norm, code)

    payment_by_code = {}
    for r in payment_rows:
        label = r.get("therapy_label")
        norm = _norm_label(label)
        code = label_to_code.get(norm)
        if not code:
            continue
        payment_by_code[code] = _to_decimal(r.get("payment_per_delivery_per_patient_usd"))

    # Resolve active patients from overrides
    override_rows = _read_csv_dicts(PATIENT_OVERRIDES_PATH)
    if override_rows:
        override_headers = set(override_rows[0].keys())
    else:
        override_headers = set()

    patient_field = "active_patients" if "active_patients" in override_headers else "patient_count"

    best_override_by_code = {}
    for r in override_rows:
        code = str(r.get("therapy_code", "")).strip()
        if code not in in_scope_codes:
            continue
        status = str(r.get("status", "")).strip()
        if status != "approved":
            continue
        rev = _to_int(r.get("revision"), default=-1)
        prev = best_override_by_code.get(code)
        if prev is None or rev > prev["revision_int"]:
            best_override_by_code[code] = {
                "revision_int": rev,
                "row": r,
            }

    active_patients_by_code = {}
    for code, info in best_override_by_code.items():
        r = info["row"]
        active_patients_by_code[code] = _to_int(r.get(patient_field), default=0)

    # Compute per-therapy metrics
    results = []
    for code in sorted(in_scope_codes):
        t = therapies_by_code[code]
        therapy_name = str(t.get("therapy_name", "")).strip()

        drug_cost_per_1000 = _to_decimal(t.get("drug_cost_per_1000_mg_usd"))
        dose_mg_per_day = _to_decimal(t.get("dose_mg_per_day"))
        bag_size_ml = _to_int(t.get("bag_size_ml"))

        if bag_size_ml not in bag_cost_by_size_ml:
            raise ValueError(f"Missing bag supply cost for bag_size_ml={bag_size_ml} (therapy_code={code})")
        bag_supply_cost = bag_cost_by_size_ml[bag_size_ml]

        active_patients = active_patients_by_code.get(code, 0)
        payment_per_delivery = payment_by_code.get(code, Decimal("0"))

        def model_block(days_per_delivery: int, deliveries_per_year: int):
            annual_drug_cost = (
                drug_cost_per_1000
                * Decimal(active_patients)
                * dose_mg_per_day
                * Decimal(days_per_delivery)
                * Decimal(deliveries_per_year)
                / Decimal("1000")
            )
