import re
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


THERAPY_CATALOG_PATH = Path("/root/therapy_catalog.json")
BAG_SUPPLY_COST_PATH = Path("/root/bag_supply_cost.csv")
DELIVERY_PAYMENT_PATH = Path("/root/delivery_payment.csv")
PATIENT_OVERRIDES_PATH = Path("/root/patient_overrides.csv")

OUTPUT_ANALYSIS_PATH = Path("/root/infusion_batch_analysis.json")
OUTPUT_SUMMARY_PATH = Path("/root/infusion_batch_summary.md")


def _norm_label(value: str) -> str:
    if value is None:
        return ""
    return re.sub(r"[^a-z0-9]+", "", str(value).strip().lower())


def _is_true(value) -> bool:
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() == "true"


def _to_int(value, default=0) -> int:
    if value is None:
        return default
    s = str(value).strip()
    if s == "":
        return default
    return int(float(s))


def _to_decimal(value, default="0") -> Decimal:
    if value is None:
        return Decimal(default)
    s = str(value).strip()
    if s == "":
        return Decimal(default)
    # Use Decimal(str(...)) for stable parsing
    return Decimal(s)


def _money_decimal(value: Decimal) -> Decimal:
    return value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _money_str(value: Decimal) -> str:
    return f"{_money_decimal(value):.2f}"


def _read_csv_dicts(path: Path):
    with path.open("r", newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        return list(reader)


def _iter_catalog_therapies(catalog_obj):
    """Yield therapy dicts regardless of whether catalog is list/dict/nested."""
    if isinstance(catalog_obj, list):
        for item in catalog_obj:
            if isinstance(item, dict) and ("therapy_code" in item or "therapy_name" in item):
                yield item
            elif isinstance(item, dict):
                # Possibly nested
                yield from _iter_catalog_therapies(item)
        return

    if isinstance(catalog_obj, dict):
        if "therapy_code" in catalog_obj or "therapy_name" in catalog_obj:
            yield catalog_obj
            return

        # Common nesting patterns
        if "therapies" in catalog_obj and isinstance(catalog_obj["therapies"], list):
            for t in catalog_obj["therapies"]:
                if isinstance(t, dict):
                    yield t
            return

        if "service_lines" in catalog_obj and isinstance(catalog_obj["service_lines"], list):
            for sl in catalog_obj["service_lines"]:
                yield from _iter_catalog_therapies(sl)
            return

        # Fallback: recurse dict values
        for v in catalog_obj.values():
            yield from _iter_catalog_therapies(v)


def _get_aliases(therapy_entry):
    aliases = []
    for key in ("aliases", "alias", "aka", "alternate_names", "alt_names"):
        if key not in therapy_entry:
            continue
        v = therapy_entry.get(key)
        if v is None:
            continue
        if isinstance(v, list):
            aliases.extend([str(x) for x in v if str(x).strip() != ""])
        else:
            s = str(v).strip()
            if s:
                aliases.append(s)
    return aliases


def main():
    # Load therapy catalog
    with THERAPY_CATALOG_PATH.open("r", encoding="utf-8") as f:
        catalog = json.load(f)

    all_therapies = list(_iter_catalog_therapies(catalog))
    in_scope = [t for t in all_therapies if _is_true(t.get("include_in_review"))]

    # Index in-scope therapies
    therapies_by_code = {}
    for t in in_scope:
        code = str(t.get("therapy_code", "")).strip()
        if not code:
            continue
        therapies_by_code[code] = t

