            if name is None:
                continue
            norm = _norm_label(name)
            if not norm:
                continue
            # Keep first mapping for determinism if collisions exist
            label_to_code.setdefault(norm, code)

    payment_by_code = {}
    for r in payment_rows:
        label = r.get("therapy_label")
        norm = _norm_label(label)
        code = label_to_code.get(norm)
        if not code:
