        if not code:
            continue
        payment_by_code[code] = _to_decimal(r.get("payment_per_delivery_per_patient_usd"))

    # Resolve active patients from overrides
    override_rows = _read_csv_dicts(PATIENT_OVERRIDES_PATH)
    if override_rows:
        override_headers = set(override_rows[0].keys())
    else:
        override_headers = set()

    patient_field = "active_patients" if "active_patients" in override_headers else "patient_count"

    best_override_by_code = {}
    for r in override_rows:
        code = str(r.get("therapy_code", "")).strip()
        if code not in in_scope_codes:
            continue
        status = str(r.get("status", "")).strip()
        if status != "approved":
            continue
        rev = _to_int(r.get("revision"), default=-1)
        prev = best_override_by_code.get(code)
        if prev is None or rev > prev["revision_int"]:
            best_override_by_code[code] = {
                "revision_int": rev,
                "row": r,
            }

    active_patients_by_code = {}
    for code, info in best_override_by_code.items():
        r = info["row"]
        active_patients_by_code[code] = _to_int(r.get(patient_field), default=0)

    # Compute per-therapy metrics
    results = []
    for code in sorted(in_scope_codes):
        t = therapies_by_code[code]
        therapy_name = str(t.get("therapy_name", "")).strip()

        drug_cost_per_1000 = _to_decimal(t.get("drug_cost_per_1000_mg_usd"))
        dose_mg_per_day = _to_decimal(t.get("dose_mg_per_day"))
        bag_size_ml = _to_int(t.get("bag_size_ml"))

        if bag_size_ml not in bag_cost_by_size_ml:
            raise ValueError(f"Missing bag supply cost for bag_size_ml={bag_size_ml} (therapy_code={code})")
        bag_supply_cost = bag_cost_by_size_ml[bag_size_ml]

        active_patients = active_patients_by_code.get(code, 0)
        payment_per_delivery = payment_by_code.get(code, Decimal("0"))

        def model_block(days_per_delivery: int, deliveries_per_year: int):
            annual_drug_cost = (
                drug_cost_per_1000
                * Decimal(active_patients)
                * dose_mg_per_day
                * Decimal(days_per_delivery)
                * Decimal(deliveries_per_year)
                / Decimal("1000")
            )
            annual_supply_cost = bag_supply_cost * Decimal(active_patients) * Decimal(deliveries_per_year)
            annual_revenue = payment_per_delivery * Decimal(active_patients) * Decimal(deliveries_per_year)
            annual_margin = annual_revenue - annual_drug_cost - annual_supply_cost
            return {
                "days_per_delivery": days_per_delivery,
                "deliveries_per_year": deliveries_per_year,
                "annual_drug_cost_usd": _money_str(annual_drug_cost),
                "annual_supply_cost_usd": _money_str(annual_supply_cost),
                "annual_revenue_usd": _money_str(annual_revenue),
                "annual_margin_usd": _money_str(annual_margin),
                # Keep numeric for internal aggregation
                "_annual_margin_dec": _money_decimal(annual_margin),
            }

        m7 = model_block(7, 52)
        m14 = model_block(14, 26)

        margin_diff = m14["_annual_margin_dec"] - m7["_annual_margin_dec"]

        results.append(
            {
                "therapy_code": code,
                "therapy_name": therapy_name,
                "active_patients": active_patients,
                "drug_cost_per_1000_mg_usd": _money_str(drug_cost_per_1000),
                "dose_mg_per_day": float(dose_mg_per_day) if dose_mg_per_day % 1 != 0 else int(dose_mg_per_day),
                "bag_size_ml": bag_size_ml,
                "bag_supply_cost_usd": _money_str(bag_supply_cost),
                "payment_per_delivery_per_patient_usd": _money_str(payment_per_delivery),
                "model_7_day": {
                    k: v for k, v in m7.items() if not k.startswith("_")
                },
                "model_14_day": {
                    k: v for k, v in m14.items() if not k.startswith("_")
                },
                "annual_margin_difference_14_minus_7_usd": _money_str(margin_diff),
                "_annual_margin_7_dec": m7["_annual_margin_dec"],
                "_annual_margin_14_dec": m14["_annual_margin_dec"],
                "_annual_margin_diff_dec": _money_decimal(margin_diff),
            }
        )

    # Totals
    total_7 = sum((t["_annual_margin_7_dec"] for t in results), Decimal("0.00"))
    total_14 = sum((t["_annual_margin_14_dec"] for t in results), Decimal("0.00"))
    total_diff = sum((t["_annual_margin_diff_dec"] for t in results), Decimal("0.00"))

    total_7_q = _money_decimal(total_7)
    total_14_q = _money_decimal(total_14)
    total_diff_q = _money_decimal(total_diff)
    abs_total_diff_q = _money_decimal(abs(total_diff_q))

    threshold = Decimal("15000")
    if abs_total_diff_q < threshold:
        decision = "move_to_14_day"
    else:
        decision = "keep_7_day"

    justification = (
        f"Absolute total annual margin difference (14 minus 7) is ${_money_str(abs_total_diff_q)} "
        f"against a ${_money_str(threshold)} threshold; total 7-day margin=${_money_str(total_7_q)}, "
        f"total 14-day margin=${_money_str(total_14_q)}."
    )

    # Strip internal fields before writing
    therapies_out = []
    for t in results:
        t2 = dict(t)
        for k in [
            "_annual_margin_7_dec",
            "_annual_margin_14_dec",
            "_annual_margin_diff_dec",
        ]:
            t2.pop(k, None)
        therapies_out.append(t2)

    output = {
        "assumptions": {
            "deliveries_per_year_7_day": 52,
            "deliveries_per_year_14_day": 26,
            "days_per_delivery_7_day": 7,
            "days_per_delivery_14_day": 14,
            "switch_threshold_usd": 15000,
            "patient_override_rule": "highest approved revision per therapy_code",
        },
        "therapies": therapies_out,
        "totals": {
            "total_annual_margin_7_day_usd": _money_str(total_7_q),
            "total_annual_margin_14_day_usd": _money_str(total_14_q),
            "total_annual_margin_difference_14_minus_7_usd": _money_str(total_diff_q),
            "absolute_total_margin_difference_usd": _money_str(abs_total_diff_q),
        },
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }

    with OUTPUT_ANALYSIS_PATH.open("w", encoding="utf-8") as f:
        json.dump(output, f, indent=2)
        f.write("\n")

    # Summary markdown (4-8 non-empty lines)
    total_7_f = float(total_7_q)
    total_14_f = float(total_14_q)
    abs_diff_f = float(abs_total_diff_q)

    lines = [
        "Infusion batch margin summary",
        f"Total 7-day margin: ${'{:,.2f}'.format(total_7_f)}",
        f"Total 14-day margin: ${'{:,.2f}'.format(total_14_f)}",
        f"Absolute difference: ${'{:,.2f}'.format(abs_diff_f)}",
        f"Decision: {decision}",
    ]

    with OUTPUT_SUMMARY_PATH.open("w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
